entity User {
    mid: String,
    password: String,
    securityQuestion?: String,
};

entity Patient in [User] {
    isActive: Bool,
};

entity Hcp in [User];

entity Lhcp in [Hcp] {
    hospitals: Set<Hospital>,
};

entity Administrator in [User];

entity EmergencyResponder in [User];

entity Uap in [User];

entity PersonalRepresentative in [User];

entity PublicHealthAgent in [User];

entity LabTechnician in [User];

entity SoftwareTester in [User];

entity Hospital;

entity Session {
    user: User,
    isActive: Bool,
};

entity SystemSettings {
    inactivityPeriodLength: duration,
};

entity MedicalRecord {
    patient: Patient,
};

entity DemographicInformation {
    patient: Patient,
};

entity DiagnosticInformation {
    patient: Patient,
    isRestricted: Bool,
    restrictionAllowed: Bool,
    allowedAudience: String,
    allowedAudienceType: DiagnosticInformationAudience,
};

entity OfficeVisit {
    patient: Patient,
    lhcp: Lhcp,
    hospital: Hospital,
    surveyTaken: Bool,
};

entity PersonalHealthInformation {
    patient: Patient,
};

entity FamilyHistory {
    patient: Patient,
};

entity Immunization {
    patient: Patient,
};

entity AccessLog {
    patient: Patient,
    accessorName: String,
    accessorRoleRelativeToPatient: String,
    dateTime: datetime,
    transactionType: String,
};

entity ProviderDesignation {
    patient: Patient,
    lhcp: Lhcp,
    isDesignated: Bool,
};

entity PersonalRepresentativeRelationship {
    patient: Patient,
    representative: User,
    isActive: Bool,
};

entity DiagnosticInformationAudience enum ["DesignatedLicensedHealthCareProfessionals", "OtherLicensedHealthCareProfessionals", "NoOne"];

